package com.project.w_3d_world.features.wallet.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import lombok.*;
@Entity @Table(name="wallet_ledgers") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class WalletLedger { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="ledger_id") private Integer id; @Column(name="wallet_id",nullable=false) private Integer walletId; @Column(name="entry_type",nullable=false) private String entryType; @Column(name="balance_bucket",nullable=false) private String bucket; @Column(name="signed_amount",nullable=false) private BigDecimal amount; @Column(name="balance_after",nullable=false) private BigDecimal balanceAfter; @Column(name="seller_earning_id") private Integer earningId; @Column(name="transaction_id") private Integer transactionId; @Column(name="idempotency_key",nullable=false,unique=true) private String idempotencyKey; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public WalletLedger(int wallet,String type,String bucket,BigDecimal amount,BigDecimal after,Integer earning,String key){walletId=wallet;entryType=type;this.bucket=bucket;this.amount=amount;balanceAfter=after;earningId=earning;idempotencyKey=key;}
 public WalletLedger(int wallet,String type,String bucket,BigDecimal amount,BigDecimal after,Integer transaction,Integer earning,String key){walletId=wallet;entryType=type;this.bucket=bucket;this.amount=amount;balanceAfter=after;transactionId=transaction;earningId=earning;idempotencyKey=key;} }
